<?php
declare(strict_types=1); require __DIR__.'/../config.php'; require_login('admin');
$id=(int)($_GET['id']??0); $s=db()->prepare('SELECT id,title,public_token,(SELECT COUNT(*) FROM questions q WHERE q.exam_id=exams.id) AS question_count FROM exams WHERE id=?'); $s->execute([$id]); $e=$s->fetch(); if(!$e) exit('Ujian tidak ditemukan.');
if((int)$e['question_count']<1){ header('Location: questions.php?id='.$id.'&need_questions=1'); exit; }
if(empty($e['public_token'])){ $t=bin2hex(random_bytes(20)); db()->prepare('UPDATE exams SET public_token=? WHERE id=?')->execute([$t,$id]); $e['public_token']=$t; }
$base=rtrim(dirname(dirname($_SERVER['SCRIPT_NAME'])),'/\\'); $link=(isset($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off'?'https':'http').'://'.$_SERVER['HTTP_HOST'].$base.'/peserta/access.php?exam='.rawurlencode($e['public_token']);
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Link Ujian</title><style>body{font-family:Arial;background:#f5f7fb;padding:30px}.card{max-width:800px;margin:auto;background:#fff;padding:25px;border-radius:16px;border:1px solid #e4e7ec;box-shadow:0 10px 28px #10182812}.link-help{margin:14px 0;padding:12px 14px;background:#eef4ff;border:1px solid #cfe0ff;border-radius:10px;color:#24549b;line-height:1.55}input{width:100%;padding:13px;box-sizing:border-box}button{margin-top:12px;padding:10px 15px;background:#175cd3;color:#fff;border:0;border-radius:8px}</style><link rel="stylesheet" href="assets/admin-ui.css">
</head><body><div class="card"><h1>Link Ujian</h1><h2><?=htmlspecialchars($e['title'])?></h2><p>Siapa pun yang memiliki link ini dapat mengerjakan. Peserta cukup memasukkan email.</p><div class="link-help">Gunakan link ini untuk peserta. Jika aplikasi berjalan di XAMPP, pastikan HP dan komputer berada pada jaringan Wi-Fi/LAN yang sama.</div><input id="link" value="<?=htmlspecialchars($link)?>" readonly><button id="copyLink" type="button">Salin Link</button><script>document.getElementById('copyLink').addEventListener('click',async function(){const v=document.getElementById('link').value;try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(v)}else{const i=document.getElementById('link');i.select();document.execCommand('copy')}this.textContent='Tersalin ✓';setTimeout(()=>this.textContent='Salin Link',1800)}catch(e){alert('Gagal menyalin otomatis. Silakan salin link secara manual.')}}</script><p><a href="index.php">Kembali ke Admin</a></p></div></body></html>